package com.ruoyi.paiflow.service;
import com.alibaba.fastjson2.*;
import com.ruoyi.common.exception.ServiceException;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** 原Factory实际调用为预期；此处只验可信Map恢复，不冒充Provider或UAT。 */
class ModelTrustedInputMapTest {
 static JSONArray cases() throws Exception {try(var in=ModelTrustedInputMapTest.class.getResourceAsStream("/fixtures/model-input-map-golden.json")){return JSON.parseObject(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)).getJSONArray("cases");}}
 @Test void actualFactoryFirstInputOrderAndLiteralConversionsSurvivePrivateSnapshot() throws Exception {for(Object raw:cases()){var c=(JSONObject)raw;var task=c.getJSONObject("assignment");var node=ModelOperationJson.copy(c.getJSONObject("nodeJson"));ModelNodeSemantics.normalize(node);var values=WorkflowInputSources.values(task.getJSONObject("dsl"),node,task.getJSONObject("input"),new JSONArray(),new HashMap<>());String snapshot=ModelMessageSources.verifiedInputsJson(values);var recovered=ModelMessageSources.verifiedValues(node,snapshot);assertEquals(c.getJSONArray("actualOperations").getJSONArray(0).getJSONObject(5).getJSONArray("messages"),ModelMessageSources.expected(node,recovered,new JSONArray()),c.getString("name"));if(c.getString("name").contains("first-z")){assertEquals("z_first",recovered.keySet().iterator().next());String reordered=ModelOperationJson.canonical(values,ModelOperationJson.REQUEST_BYTES);assertEquals("z_first",ModelMessageSources.verifiedValues(node,reordered).keySet().iterator().next());}}}
 @Test void privateValuesAreExactAndPreserveNegativeZeroAndNull(){var node=JSONObject.of("id","spark-llm::m","data",JSONObject.of("inputs",new JSONArray(List.of(JSONObject.of("name","z"),JSONObject.of("name","a"))),"nodeParam",JSONObject.of("template","{{z}}|{{a}}")));var values=ModelMessageSources.sourceObject("{\"a\":null,\"z\":-0.0}");var restored=ModelMessageSources.verifiedValues(node,ModelMessageSources.verifiedInputsJson(values));assertEquals(Double.doubleToRawLongBits(-0.0),Double.doubleToRawLongBits(((Number)restored.get("z")).doubleValue()));assertTrue(restored.containsKey("a"));assertNull(restored.get("a"));assertEquals(List.of("z","a"),new ArrayList<>(restored.keySet()));assertEquals(403,assertThrows(ServiceException.class,()->ModelMessageSources.verifiedValues(node,"{\"z\":0}")).getCode());assertEquals(403,assertThrows(ServiceException.class,()->ModelMessageSources.verifiedValues(node,"{\"a\":null,\"z\":0,\"extra\":1}")).getCode());node.getJSONObject("data").getJSONArray("inputs").add(JSONObject.of("name","z"));assertEquals(409,assertThrows(ServiceException.class,()->ModelMessageSources.verifiedValues(node,"{\"a\":null,\"z\":0}")).getCode());}
 @Test void oldBareModelTargetReadsOnlyPresentRealRoot(){var run=new com.ruoyi.paiflow.domain.RunRecord();run.setId("run");run.setLeaseId("lease");run.setAttempt(1);run.setLastEventSeq(0L);run.setAssignmentJson("{\"input\":{\"q\":null}}");var node=JSONObject.of("id","spark-llm::bare","data",JSONObject.of("inputs",new JSONArray(List.of(JSONObject.of("name","q","type","string"))),"nodeParam",new JSONObject()));var graph=JSONObject.of("nodes",new JSONArray(List.of(node)),"edges",new JSONArray());var sources=new CompletedOutputSources(null,null,null);assertTrue(sources.values(run,graph,node,new JSONArray()).containsKey("q"));run.setAssignmentJson("{\"input\":{}}");assertEquals(403,assertThrows(ServiceException.class,()->sources.values(run,graph,node,new JSONArray())).getCode());node.put("id","text-joiner::bare");run.setAssignmentJson("{\"input\":{\"q\":1}}");assertEquals(403,assertThrows(ServiceException.class,()->sources.values(run,graph,node,new JSONArray())).getCode());}
 @Test void oldBareModelAncestorKeepsOriginalFixedNodeAndFrameSource() throws Exception {var c=ModelMessageSources.sourceObject(CompletedOutputSourcesTest.cases().getJSONObject(0).toJSONString(JSONWriter.Feature.WriteMapNullValue));var node=c.getJSONObject("nodeJson");node.getJSONObject("data").getJSONArray("inputs").getJSONObject(0).remove("schema");var id=node.getString("id");var task=c.getJSONObject("assignment");var original=DataWorkerOperationService.find(task.getJSONObject("dsl"),id);original.getJSONObject("data").put("inputs",node.getJSONObject("data").getJSONArray("inputs"));var f=new CompletedOutputSourcesTest().fixture(c);f.sources().verify(f.run(),task.getJSONObject("dsl"),f.target(),f.events());task.getJSONObject("input").remove("question");f.run().setAssignmentJson(task.toJSONString(JSONWriter.Feature.WriteMapNullValue));assertEquals(403,assertThrows(ServiceException.class,()->f.sources().verify(f.run(),task.getJSONObject("dsl"),f.target(),f.events())).getCode());}
}
